  var MISSING = {"手": ["甲骨文"], "森": ["金文", "楚簡", "戰國金文"], "岩": ["甲骨文", "金文", "楚簡", "小篆"], "坐": ["金文"], "蛇": ["甲骨文", "金文", "楚簡"], "猴": ["甲骨文", "金文", "楚簡", "戰國金文"], "狗": ["甲骨文", "金文"], "猪": ["甲骨文", "金文", "戰國金文"], "李": ["甲骨文"]};

  var STATS = {"chars": 106, "full": 97, "eras": [{"key": "甲骨文", "cov": 99}, {"key": "金文", "cov": 99}, {"key": "楚簡", "cov": 102}, {"key": "戰國金文", "cov": 103}, {"key": "小篆", "cov": 105}]};

  var ORDER = ERAS.map(function (e) { return e.key; });

  global.AncientGlyphs = {
    ERAS: ERAS,
    SOURCES: SOURCES,
    chars: CHARS,
    stats: STATS,

    /** 某一阶段**主要**来自哪个来源（含授权状态）。注意这是「期」级的，不是「格」级的。 */
    eraSource: function (era) {
      for (var i = 0; i < ERAS.length; i++) {
        if (ERAS[i].key === era) return SOURCES[ERAS[i].src] || null;
      }
      return null;
    },

    /** **某一格**（字, 期）来自哪个来源。显示出处要用这个，不要用 eraSource。
     *
     *  绝大多数格与本期主来源一致，GLYPH_SRC 只记**不一样**的那些
     *  （汉典补进来的 9 格），所以它小、且改起来一眼能看完。
     *  甲骨文那一期的主来源仍是 CDP，但其中 3 格来自汉典 ——
     *  用 eraSource 报出处会把那 3 格说成中研院的。 */
    glyphSource: function (ch, era) {
      var m = GLYPH_SRC[ch];
      return SOURCES[m && m[era]] || this.eraSource(era);
    },

    /** 楷书那层的归一化参数 → [scale, tx, ty]，没有就返回 null（照原样渲染） */
    kaiFit: function (ch) { return KAI_FIT[ch] || null; },

    /** 该字有没有这个阶段 */
    has: function (ch, era) {
      var e = CHARS[ch];
      if (!e) return false;
      if (era == null) return true;          // 不指定阶段 = 有没有这个字
      return !!e[era] && e[era].length > 0;
    },

    /** 取字形 path 数组。era 省略时取时间最早的那个可用阶段。 */
    paths: function (ch, era) {
      var e = CHARS[ch];
      if (!e) return [];
      if (era != null) return e[era] || [];
      for (var i = 0; i < ORDER.length; i++) {
        if (e[ORDER[i]] && e[ORDER[i]].length) return e[ORDER[i]];
      }
      return [];
    },

    /** 这个字实际有哪些阶段（按时间序） */
    erasOf: function (ch) {
      var e = CHARS[ch] || {};
      return ORDER.filter(function (k) { return e[k] && e[k].length; });
    },

    /** 这个字缺哪些阶段 */
    missingOf: function (ch) {
      return MISSING[ch] || [];
    },

    /** 全部字都有的阶段（用来判断能不能全字库展示某段） */
    commonEras: function () {
      return ORDER.filter(function (k) {
        return STATS.eras.some(function (s) { return s.key === k && s.cov === STATS.chars; });
      });
    }
  };
